from typing import List


def sort_numbers(numbers: str) -> str:
    number_map = {
        'zero': 0,
        'one': 1,
        'two': 2,
        'three': 3,
        'four': 4,
        'five': 5,
        'six': 6,
        'seven': 7,
        'eight': 8,
        'nine': 9
    }

    if not numbers.strip():
        return ""

    words = numbers.split()
    try:
        mapped = [(number_map[word], word) for word in words]
    except KeyError:
        return ""

    mapped.sort(key=lambda x: x[0])
    return " ".join(word for _, word in mapped)

