        (1.7, 'C'),
        (1.3, 'C-'),
        (1.0, 'D+'),
        (0.7, 'D'),
        (0.0, 'D-'),
    ]

    result = []
    for g in grades:
        if not isinstance(g, (int, float)):
            raise TypeError("Grades must be numeric")
        g = round(g, 1)
        if g == 4.0:
            result.append('A+')
        elif g == 0.0:
            result.append('E')
        else:
            for threshold, letter in grade_map:
                if g > threshold:
                    result.append(letter)
                    break
            else:
                result.append('E')
