from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

def closest_integer(value):
    try:
        d = Decimal(value)
    except InvalidOperation:
        raise ValueError("Invalid number string")

    # Round half away from zero
    if d == d.to_integral():
        return int(d)

    # Use ROUND_HALF_UP which rounds half away from zero for positive numbers
    # For negative numbers, we need to adjust because ROUND_HALF_UP rounds toward zero for negatives
    # So we take absolute value, round, then restore sign
    sign = 1 if d >= 0 else -1
    abs_d = abs(d)
    rounded_abs = abs_d.to_integral_value(rounding=ROUND_HALF_UP)
    return sign * int(rounded_abs)

