def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # dp[pos][t] = lexicographically smallest path of length t ending at pos
    # We'll store as tuple of values
    dp = [[None] * (k + 1) for _ in range(n * n)]

    # Initialize for length 1
    for i in range(n):
        for j in range(n):
            idx = i * n + j
            dp[idx][1] = (grid[i][j],)

    # Build transitions
    neighbors = [[] for _ in range(n * n)]
    for i in range(n):
        for j in range(n):
            idx = i * n + j
            for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    neighbors[idx].append(ni * n + nj)

    # DP for lengths 2..k
    for t in range(2, k + 1):
        for idx in range(n * n):
            best = None
            for nb in neighbors[idx]:
                prev = dp[nb][t - 1]
                if prev is not None:
                    candidate = prev + (grid[idx // n][idx % n],)
                    if best is None or candidate < best:
                        best = candidate
            dp[idx][t] = best

    # Find global minimum among all positions for length k
    best_path = None
    for idx in range(n * n):
        if dp[idx][k] is not None:
            if best_path is None or dp[idx][k] < best_path:
                best_path = dp[idx][k]

    return list(best_path)

