def do_algebra(operator, operand):
    # Define precedence and associativity
    precedence = {'+': 1, '-': 1, '*': 2, '//': 2, '**': 3}
    right_assoc = {'**': True}

    # Convert infix to postfix using Shunting-yard algorithm
    output = []
    op_stack = []

    for op in operator:
        while op_stack and (precedence[op_stack[-1]] > precedence[op] or 
                           (precedence[op_stack[-1]] == precedence[op] and 
                            op not in right_assoc and op_stack[-1] not in right_assoc)):
            output.append(op_stack.pop())
        op_stack.append(op)

    while op_stack:
        output.append(op_stack.pop())

    # Evaluate postfix expression
    stack = []
    operand_idx = 0
    for token in output:
        if token in precedence:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '//':
                stack.append(a // b)
            elif token == '**':
                stack.append(a ** b)
        else:
            stack.append(operand[operand_idx])
            operand_idx += 1

    return stack[0]

