def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0

    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        new_dp = [0] * (m + 1)
        for j in range(0, min(i, m) + 1):
            if j == 0:
                new_dp[j] = 1
            else:
                new_dp[j] = (i - j) * dp[j - 1] + (j + 1) * dp[j]
        dp = new_dp

    return dp[m]

