        k = -x0 // step_x
        for candidate_k in range(k - 2, k + 3):
            x = x0 + candidate_k * step_x
            y = y0 + candidate_k * step_y
            if x >= 0 and y >= 0:
                return (x, y)
    elif step_y != 0:
        k = -y0 // step_y
        for candidate_k in range(k - 2, k + 3):
            x = x0 + candidate_k * step_x
            y = y0 + candidate_k * step_y
            if x >= 0 and y >= 0:
                return (x, y)
    else:
        if x0 >= 0 and y0 >= 0:
            return (x0, y0)
        return None

    # If no non-negative solution found, return any integer solution
    return (x0, y0)

